import{_ as e,o as l,c as a,a2 as r}from"./chunks/framework.BWuWLRhz.js";const x=JSON.parse('{"title":"設定項目リファレンス","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/settings/index.md","filePath":"ja-JP/user-guide/settings/index.md","lastUpdated":1788366161000}'),n={name:"ja-JP/user-guide/settings/index.md"};function s(d,t,i,o,g,f){return l(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="設定項目リファレンス" tabindex="-1">設定項目リファレンス <a class="header-anchor" href="#設定項目リファレンス" aria-label="Permalink to &quot;設定項目リファレンス&quot;">​</a></h1><p>Lertaro は、柔軟で詳細なカスタマイズオプションを提供します。検索バーのピクセル単位のサイズ調整から、グローバルホットキーの設定、ドライブごとのインデックス周期の調整、サードパーティ製プラグインやワークスペースの管理まで、すべてを設定センターから行えます。</p><h2 id="_1-ウィンドウ機能と操作性" tabindex="-1">1. ウィンドウ機能と操作性 <a class="header-anchor" href="#_1-ウィンドウ機能と操作性" aria-label="Permalink to &quot;1. ウィンドウ機能と操作性&quot;">​</a></h2><ul><li><strong>自由なリサイズと最大化</strong>：設定ウィンドウは境界線をドラッグしてのサイズ変更や、タイトルバーのダブルクリックによる最大化に対応しており、ウィンドウサイズは自動的に記憶されます。</li><li><strong>設定全体のあいまい検索</strong>：設定ウィンドウのタイトルバー右上にある検索ボックスから、すべての設定項目を検索できます。検索にはメイン検索と同じ fzf あいまい一致エンジンが使用され、プラグイン設定やアクション項目もカバーします。結果を選択すると該当する設定ページへ瞬時にジャンプし、対象の項目が点滅ハイライト表示されます。</li><li><strong>スクロール可能なタブバー</strong>：複数のサブタブを持つセクション（一般、ホットキー、インデックスなど）では、言語によって文字幅が長くなっても左右のスクロール矢印によりすべてのタブにアクセスできます。</li></ul><h2 id="_2-設定セクション一覧" tabindex="-1">2. 設定セクション一覧 <a class="header-anchor" href="#_2-設定セクション一覧" aria-label="Permalink to &quot;2. 設定セクション一覧&quot;">​</a></h2><p>左側のサイドバーには以下の主要な設定セクションが配置されています。</p><table tabindex="0"><thead><tr><th style="text-align:left;">セクション</th><th style="text-align:left;">主な設定内容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><a href="./service-status.html">サービス状態</a></strong></td><td style="text-align:left;">Windows バックグラウンドサービスの状態監視、および Service / App / Hook プロセスのリアルタイムログビューアー。</td></tr><tr><td style="text-align:left;"><strong><a href="./index-drives.html">インデックス管理</a></strong></td><td style="text-align:left;">ローカルドライブ（NTFS / ReFS / FAT32）、ネットワーク共有（SMB / NAS）、WSL ディストリビューション、個別フォルダー、除外ルール。</td></tr><tr><td style="text-align:left;"><strong><a href="./general.html">一般設定</a></strong></td><td style="text-align:left;">自動起動、ハードウェアアクセラレーション、IPC 互換サービス、検索バーのサイズ調整、テーブル列の並び替え、プレビュー設定。</td></tr><tr><td style="text-align:left;"><strong><a href="./hotkeys-page.html">ホットキー</a></strong></td><td style="text-align:left;">グローバルホットキー、ナビゲーションキー、プラグインアクションのショートカット、プロセスブラックリスト、全画面アプリの除外。</td></tr><tr><td style="text-align:left;"><strong><a href="./plugins.html">プラグイン</a></strong></td><td style="text-align:left;">インストール済みプラグイン一覧、コンポーネントごとの有効/無効化、設定フォーム、Flow Launcher コミュニティプラグインの管理、実行状態の確認。</td></tr><tr><td style="text-align:left;"><strong><a href="./localsend.html">LocalSend</a></strong></td><td style="text-align:left;">LocalSend 公式クライアント互換の LAN 内ファイル/テキスト転送設定（デバイス名、ポート、PIN 認証、自動保存）。</td></tr><tr><td style="text-align:left;"><strong><a href="./favorites.html">お気に入り</a></strong></td><td style="text-align:left;">よく使うフォルダー、ファイル、Web サイトの登録、並び替え、ピンイン検索。</td></tr><tr><td style="text-align:left;"><strong><a href="./history.html">検索履歴</a></strong></td><td style="text-align:left;">検索結果の実行履歴と入力キーワード履歴の管理、優先表示、履歴のクリア。</td></tr><tr><td style="text-align:left;"><strong><a href="./quick-launch.html">クイック起動</a></strong></td><td style="text-align:left;">手動のクイック起動項目を管理し、空のクイック検索ウィンドウに表示する動的データソースを選択します。</td></tr><tr><td style="text-align:left;"><strong><a href="./quick-panel.html">クイックパネル</a></strong></td><td style="text-align:left;">アクティブウィンドウに吸着するフローティングワークスペース、フォルダーの集約表示、ドラッグ＆ドロップ登録、プラグイン動的タブ。</td></tr><tr><td style="text-align:left;"><strong><a href="./appearance.html">外観とテーマ</a></strong></td><td style="text-align:left;">ライト / ダーク / システム連動モードの切り替え、標準および付属テーマのリアルタイム縮小プレビューカード。</td></tr><tr><td style="text-align:left;"><strong><a href="./about.html">バージョン情報</a></strong></td><td style="text-align:left;">各コンポーネントのバージョン、ユーザー/マシンのデータディレクトリへの直接アクセス、バックアップローテーション、自動更新。</td></tr></tbody></table><p>以降の各ページでは、セクションごとの詳細な設定項目、設定範囲、既定の動作について順を追って解説します。</p>',8)])])}const y=e(n,[["render",s]]);export{x as __pageData,y as default};
